JSON.stringify((function(){
    const R=(e)=>{const r=e.getBoundingClientRect();return {t:Math.round(r.top),b:Math.round(r.bottom),h:Math.round(r.height),w:Math.round(r.width)};};
    const cl=document.querySelector('[data-im="submit-cluster"]');
    const cs=getComputedStyle(cl);
    const out={cluster:R(cl), display:cs.display, direction:cs.flexDirection, wrap:cs.flexWrap, kids:[]};
    for(const k of cl.children){ out.kids.push({cls:k.className, ...R(k), text:(k.textContent||'').trim().slice(0,40)}); }
    const box=document.querySelector('[data-im="submit-details-box"]');
    out.detailsOpen = !!box;
    return out;
  })())
